/* v4: ปฏิทินจริง, แผนที่จริง (Leaflet/OSM), แก้ไขผู้ใช้, สร้าง/แก้ไขรอบจัดเก็บ */
const TM=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'],TONE={'ประกาศแล้ว':'green','ร่าง':'amber','นัดหมายใหม่':'blue'};
Object.assign(state,{cm:{y:2027,m:0},cd:null,er:null,rounds:[{id:1,y:2027,m:0,d:15,area:'หมู่ 5',hh:120,status:'ประกาศแล้ว'},{id:2,y:2027,m:0,d:22,area:'หมู่ 5',hh:6,status:'นัดหมายใหม่'},{id:3,y:2027,m:1,d:15,area:'หมู่ 6',hh:98,status:'ร่าง'}],users:[['นายสมชาย ใจดี','พนักงานเก็บขยะ','ใช้งานอยู่'],['นางสาวสุภาวดี มั่นคง','เจ้าหน้าที่ฝ่ายบัญชี','ใช้งานอยู่'],['นายสมพงษ์ พรชัย','หัวหน้าฝ่าย','ใช้งานอยู่'],['นายอนันต์ มีสุข','พนักงานเก็บขยะ','ระงับชั่วคราว']]});
const _s2=shell;shell=c=>{const h=_s2(c),r=roles[state.role];return h.replace(r.icon+' '+r.label+'</button>',r.icon+'<span class="rc-l"> '+r.label+'</span></button>')};
function openModal(h){closeModal(1);const m=document.createElement('div');m.id='mdl';m.className='modal-backdrop';m.innerHTML=`<div class="modal">${h}</div>`;m.onclick=e=>{if(e.target===m)closeModal()};document.body.appendChild(m)}
function closeModal(q){document.getElementById('mdl')?.remove()}
/* ปฏิทิน */
function calMove(n){let{y,m}=state.cm;m+=n;if(m<0){m=11;y--}if(m>11){m=0;y++}state.cm={y,m};state.cd=null;render()}
function feeCalendar(){const{y,m}=state.cm,first=new Date(y,m,1).getDay(),dim=new Date(y,m+1,0).getDate(),ev=d=>state.rounds.filter(r=>r.y===y&&r.m===m&&r.d===d),t=new Date(),cells=[...Array(first).fill(0),...Array.from({length:dim},(_,i)=>i+1)];
 return shell(`${pageHead('ปฏิทินกำหนดการ',`${TM[m]} ${y+543}`,`<button class="btn btn-secondary" onclick="calMove(-1)">‹ ก่อนหน้า</button><button class="btn btn-secondary" onclick="calMove(1)">ถัดไป ›</button><button class="btn btn-primary" onclick="state.er=null;go('fee-create')">＋ สร้างรอบ</button>`)}<div class="card"><div class="cal">${['อา','จ','อ','พ','พฤ','ศ','ส'].map(w=>`<b class="cw">${w}</b>`).join('')}${cells.map(d=>d?`<button class="cd ${state.cd===d?'sel':''} ${t.getFullYear()===y&&t.getMonth()===m&&t.getDate()===d?'today':''}" onclick="state.cd=${d};render()"><span>${d}</span>${ev(d).map(r=>`<i class="ev ${TONE[r.status]}"><em>${r.area}</em></i>`).join('')}</button>`:'<span></span>').join('')}</div><div class="dlg"><span><i style="background:#16a34a"></i>ประกาศแล้ว</span><span><i style="background:#d9a400"></i>ร่าง</span><span><i style="background:#175cd3"></i>นัดหมายใหม่</span></div></div>${state.cd?`<div class="card" style="margin-top:14px"><h3>${state.cd} ${TM[m]} ${y+543}</h3>${ev(state.cd).map(r=>`<p>${badge(r.status,TONE[r.status])} ${r.area} • ${r.hh} ครัวเรือน <button class="btn btn-secondary" onclick="editRound(${r.id})">แก้ไข</button></p>`).join('')||'<p class="hint">ไม่มีกำหนดการในวันนี้</p>'}</div>`:''}`)}
/* รอบจัดเก็บ */
function editRound(id){state.er=id;go('fee-create')}
function delRound(id){state.rounds=state.rounds.filter(r=>r.id!==id);toast('ลบรอบแล้ว');render()}
function feeRounds(){const L=[...state.rounds].sort((a,b)=>new Date(a.y,a.m,a.d)-new Date(b.y,b.m,b.d));return shell(`${pageHead('รอบจัดเก็บค่าธรรมเนียม','จัดการกำหนดการรายเดือน',`<button class="btn btn-primary" onclick="state.er=null;go('fee-create')">＋ สร้างรอบ</button>`)}<div class="list">${L.map(r=>`<article class="list-item"><div class="thumb">📅</div><div><h3>รอบ${TM[r.m]} ${r.y+543}</h3><p>${r.d} ${TM[r.m]} • ${r.area} • ${r.hh} ครัวเรือน</p><div class="meta">${badge(r.status,TONE[r.status])}</div></div><div class="actions"><button class="btn btn-secondary" onclick="editRound(${r.id})">แก้ไข</button><button class="btn btn-ghost" onclick="state.cm={y:${r.y},m:${r.m}};state.cd=${r.d};go('fee-calendar')">ปฏิทิน</button><button class="btn btn-ghost" onclick="delRound(${r.id})">ลบ</button></div></article>`).join('')||'<div class="card"><p>ยังไม่มีรอบจัดเก็บ</p></div>'}</div>`)}
function feeCreate(){const r=state.rounds.find(x=>x.id===state.er)||{y:2027,m:1,d:15,area:'หมู่ 6',hh:98,status:'ร่าง'},v=`${r.y}-${String(r.m+1).padStart(2,'0')}-${String(r.d).padStart(2,'0')}`;
 return shell(`${pageHead(state.er?'แก้ไขรอบจัดเก็บ':'สร้างรอบจัดเก็บค่าธรรมเนียม','กำหนดวัน พื้นที่ และจำนวนครัวเรือน')}<form class="card" onsubmit="event.preventDefault();saveRound(1)"><div class="form-grid"><div class="field"><label>วันที่เข้าจัดเก็บ</label><input type="date" id="r-date" required value="${v}"></div><div class="field"><label>หมู่บ้าน/พื้นที่</label><select id="r-area">${Array.from({length:15},(_,i)=>`<option ${r.area==='หมู่ '+(i+1)?'selected':''}>หมู่ ${i+1}</option>`).join('')}</select></div><div class="field"><label>จำนวนครัวเรือน</label><input type="number" id="r-hh" min="1" required value="${r.hh}"></div><div class="field"><label>สถานะรอบ</label><select id="r-st">${['ร่าง','ประกาศแล้ว','นัดหมายใหม่'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="actions" style="justify-content:flex-end;margin-top:18px"><button type="button" class="btn btn-ghost" onclick="state.er=null;go('fee-rounds')">ยกเลิก</button><button type="button" class="btn btn-secondary" onclick="saveRound(0)">บันทึกร่าง</button><button class="btn btn-primary">ประกาศกำหนดการ</button></div></form>`)}
function saveRound(pub){const f=document.getElementById('r-date').value;if(!f)return toast('กรุณาเลือกวันที่');const[y,m,d]=f.split('-').map(Number),s=document.getElementById('r-st').value,o={y,m:m-1,d,area:document.getElementById('r-area').value,hh:+document.getElementById('r-hh').value||0,status:pub?(s==='ร่าง'?'ประกาศแล้ว':s):'ร่าง'},i=state.rounds.findIndex(x=>x.id===state.er);if(i>=0)state.rounds[i]={...state.rounds[i],...o};else state.rounds.push({id:Date.now(),...o});state.cm={y,m:m-1};state.er=null;toast(pub?'ประกาศกำหนดการแล้ว':'บันทึกร่างแล้ว');go('fee-rounds')}
/* ผู้ดูแลระบบ */
const RL=['พนักงานเก็บขยะ','เจ้าหน้าที่หน้าเคาน์เตอร์','เจ้าหน้าที่ฝ่ายบัญชี','หัวหน้าฝ่าย','ผู้ดูแลระบบ'];
function adminHome(){return shell(`${pageHead('จัดการบัญชีผู้ใช้','แก้ไขบทบาทและสถานะบัญชี',`<button class="btn btn-primary" onclick="editUser(-1)">＋ เพิ่มบัญชี</button>`)}<div class="notice">ต้นแบบจำลองตารางผู้ใช้ในฐานข้อมูล Supabase (ระบบจริงกำหนดบทบาทผ่านฐานข้อมูลโดยตรง)</div><div class="toolbar"><input class="search" placeholder="ค้นหาชื่อผู้ใช้" oninput="document.querySelectorAll('#ut .ur').forEach(r=>r.style.display=r.textContent.includes(this.value.trim())?'':'none')"></div><div class="card table-wrap"><table class="table" id="ut"><tr><th>ชื่อผู้ใช้</th><th>บทบาท</th><th>สถานะ</th><th></th></tr>${state.users.map((u,i)=>`<tr class="ur"><td>${u[0]}</td><td>${u[1]}</td><td>${badge(u[2],u[2]==='ใช้งานอยู่'?'green':'red')}</td><td><button class="btn btn-secondary" onclick="editUser(${i})">แก้ไข</button></td></tr>`).join('')}</table></div>`)}
function editUser(i){const u=i<0?['',RL[0],'ใช้งานอยู่']:state.users[i];openModal(`<h2>${i<0?'เพิ่ม':'แก้ไข'}บัญชีผู้ใช้</h2><div class="field"><label>ชื่อ–นามสกุล</label><input id="u-n" value="${u[0]}"></div><div class="field" style="margin-top:12px"><label>บทบาท</label><select id="u-r">${RL.map(x=>`<option ${x===u[1]?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>สถานะ</label><select id="u-s">${['ใช้งานอยู่','ระงับชั่วคราว'].map(x=>`<option ${x===u[2]?'selected':''}>${x}</option>`).join('')}</select></div><div class="actions" style="margin-top:16px"><button class="btn btn-primary" onclick="saveUser(${i})">บันทึก</button><button class="btn btn-ghost" onclick="closeModal()">ยกเลิก</button></div>`)}
function saveUser(i){const n=document.getElementById('u-n').value.trim();if(!n)return toast('กรุณากรอกชื่อ');const u=[n,document.getElementById('u-r').value,document.getElementById('u-s').value];i<0?state.users.push(u):state.users[i]=u;closeModal();toast('บันทึกบัญชีแล้ว');render()}
/* แผนที่จริง: Leaflet + OpenStreetMap */
wrap('complaintForm',h=>h.replace(/<div class="map" style="min-height:230px">[\s\S]*?<\/small><\/div><\/div>/,'<div id="lmap" class="lmap"></div><small class="hint" id="lcoord">แตะแผนที่หรือลากหมุดเพื่อเลือกตำแหน่งที่เกิดเหตุ</small>').replace("toast('ใช้ตำแหน่งปัจจุบันแล้ว')",'geoLocate()'));
function initMaps(){const el=document.getElementById('lmap');if(!el||!window.L||el._m)return;const c=state.complaint,map=L.map(el).setView([c.lat||19.925,c.lng||99.193],15);el._m=map;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);
 const ic=L.divIcon({html:'<div class="lpin">📍</div>',className:'',iconSize:[34,34],iconAnchor:[17,32]});let mk=null;
 const put=(a,b)=>{c.lat=a;c.lng=b;c.location=a.toFixed(5)+', '+b.toFixed(5);document.getElementById('lcoord').textContent='พิกัดที่เลือก: '+c.location;if(mk)mk.setLatLng([a,b]);else{mk=L.marker([a,b],{icon:ic,draggable:true}).addTo(map);mk.on('dragend',()=>{const p=mk.getLatLng();put(p.lat,p.lng)})}};
 map.on('click',e=>put(e.latlng.lat,e.latlng.lng));window.putPin=(a,b)=>{put(a,b);map.setView([a,b],17)};if(c.lat)put(c.lat,c.lng);setTimeout(()=>map.invalidateSize(),250)}
function geoLocate(){if(!navigator.geolocation)return toast('อุปกรณ์ไม่รองรับการระบุตำแหน่ง');toast('กำลังหาตำแหน่ง...');navigator.geolocation.getCurrentPosition(p=>window.putPin(p.coords.latitude,p.coords.longitude),()=>toast('เข้าถึงตำแหน่งไม่ได้ กรุณาอนุญาตสิทธิ์'),{enableHighAccuracy:true,timeout:10000})}
const _rr=render;render=function(){_rr();initMaps()};render();
